export const getUpdateIssueUrl = (projectId: string,
    issueId: string,) => {




  return `/api/projects/${projectId}/issues/${issueId}`
}

/**
 * @summary Mark an issue reviewed or unreviewed
 */
export const updateIssue = async (projectId: string,
    issueId: string,
    issueUpdate: IssueUpdate, options?: Parameters<typeof customFetch>[1]): Promise<SEOIssue> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<SEOIssue>(getUpdateIssueUrl(projectId,issueId),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(issueUpdate)
  }
);}





export const getUpdateIssueMutationKey = () => ['updateIssue'] as const;

export const getUpdateIssueMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateIssue>>, TError,UpdateIssueMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof updateIssue>>, TError,UpdateIssueMutationVariables, TContext> => {

const mutationKey = getUpdateIssueMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateIssue>>, UpdateIssueMutationVariables> = (props) => {
          const {projectId,issueId,data} = props ?? {};

          return  updateIssue(projectId,issueId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateIssueMutationResult = NonNullable<Awaited<ReturnType<typeof updateIssue>>>
    export type UpdateIssueMutationBody = BodyType<IssueUpdate>
    export type UpdateIssueMutationError = ErrorType<unknown>
    export type UpdateIssueMutationVariables = {projectId: string;issueId: string;data: BodyType<IssueUpdate>}

    /**
 * @summary Mark an issue reviewed or unreviewed
 */
export const useUpdateIssue = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateIssue>>, TError,UpdateIssueMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof updateIssue>>,
        TError,
        UpdateIssueMutationVariables,
        TContext
      > => {
      return useMutation(getUpdateIssueMutationOptions(options));
    }

